<script>document.querySelectorAll('.recipient-entry-form').forEach(form=>{if(form.dataset.modeReady)return;const type=form.querySelector('.recipient-form-type'),program=form.querySelector('.recipient-form-program'),category=form.querySelector('.work-category-label'),swakelola=form.querySelector('.swakelola-fields'),contractual=form.querySelector('.contractual-fields');const setMode=categoryValue=>{const contractualMode=categoryValue==='kontraktual';category.value=categoryValue;swakelola.classList.toggle('d-none',contractualMode);contractual.classList.toggle('d-none',!contractualMode);swakelola.querySelectorAll('input,select').forEach(input=>input.disabled=contractualMode);contractual.querySelectorAll('input,select').forEach(input=>input.disabled=!contractualMode)};const categoryFromCode=code=>['KAWASAN_PERMUKIMAN','PENINGKATAN_PSU'].includes(code)?'kontraktual':'swakelola';type.addEventListener('change',()=>setMode(categoryFromCode(type.selectedOptions[0]?.dataset.code)));program.addEventListener('change',()=>setMode(categoryFromCode(program.selectedOptions[0]?.dataset.code)));category.addEventListener('change',()=>setMode(category.value));const number=value=>Math.max(0,Number(String(value??'').replace(/[^0-9]/g,''))||0);const format=value=>new Intl.NumberFormat('id-ID',{maximumFractionDigits:0}).format(value);const calculate=()=>{const material=number(form.querySelector('.js-material-cost')?.value),materialProgress=Math.min(100,number(form.querySelector('.js-material-progress')?.value)),labor=number(form.querySelector('.js-labor-cost')?.value),laborProgress=Math.min(100,number(form.querySelector('.js-labor-progress')?.value));form.querySelector('.js-material-remaining').value=format(material*(1-materialProgress/100));form.querySelector('.js-labor-remaining').value=format(labor*(1-laborProgress/100))};form.querySelectorAll('.js-material-cost,.js-material-progress,.js-labor-cost,.js-labor-progress').forEach(input=>input.addEventListener('input',calculate));form.querySelectorAll('.js-material-cost,.js-labor-cost,.js-contract-value').forEach(input=>input.addEventListener('blur',()=>input.value=format(number(input.value))));setMode(category.value);calculate();form.dataset.modeReady='1'});</script>
